  form.bowlWaterMin.value = config.bowlWaterMin ?? 50;
  form.bowlWaterMax.value = config.bowlWaterMax ?? 200;
  form.bowlFoodMin.value = config.bowlFoodMin ?? 30;
  form.bowlFoodMax.value = config.bowlFoodMax ?? 100;
}

